/**
 * R5 SMS reader v2 — SYNTHETIC fixtures only.
 *
 * Written from general knowledge of public Indian bank SMS formats — never
 * copied from a phone. Payees are "QA PAYEE" / "QA STORE" / "QA CAFE" /
 * "QA EMPLOYER PVT LTD", VPAs "qa.payee@okqa", accounts XX1234 / XX9999,
 * references 000000000001, helpline numbers 18000000000. Sender addresses
 * use public DLT header IDs (the same codes every customer sees).
 */
import type { SmsLabel } from '../../features/sms-sync/parser/readSms';

export interface SmsFixtureExpect {
  label: SmsLabel;
  /** Transaction classes only. */
  type?: 'expense' | 'income';
  amountMinor?: number;
  /** null = no last-4 expected; undefined = not checked. */
  lastFour?: string | null;
  /** null = 'Unknown' merchant expected; undefined = not checked. */
  payee?: string | null;
  salary?: boolean;
  /** Canonical institution of the result. */
  institution?: string;
  /** Reported balance / limit figure in the SMS (property: never the txn amount). */
  balanceMinor?: number;
  /** Not-understood reason. */
  reason?: 'no_amount' | 'no_direction' | 'unknown_format';
  /** Account kind of the transaction. */
  accountKind?: 'bank' | 'credit_card' | 'upi' | 'other';
  /** Display bank name of the transaction. */
  bankName?: string;
  /** R5d: the other side's account digits (never used for matching). */
  counterpartyLastFour?: string;
  /** R5d: a 3-digit account mask ("Acct XX888"). */
  lastDigits?: string;
  /** R5d: a credit card bill paid from a bank a/c. */
  moneyHint?: 'card_payment';
}

export interface SmsFixture {
  name: string;
  /** Institution group for coverage counts ('generic' / 'negative' for the rest). */
  group: string;
  address: string;
  body: string;
  expect: SmsFixtureExpect;
}

const fx = (
  group: string,
  name: string,
  address: string,
  body: string,
  expect: SmsFixtureExpect,
): SmsFixture => ({ group, name, address, body, expect });

const debit = (amountMinor: number, extra: Partial<SmsFixtureExpect> = {}): SmsFixtureExpect => ({
  label: 'txn_debit',
  type: 'expense',
  amountMinor,
  ...extra,
});
const credit = (amountMinor: number, extra: Partial<SmsFixtureExpect> = {}): SmsFixtureExpect => ({
  label: 'txn_credit',
  type: 'income',
  amountMinor,
  ...extra,
});
const cardSpend = (amountMinor: number, extra: Partial<SmsFixtureExpect> = {}): SmsFixtureExpect => ({
  label: 'card_spend',
  type: 'expense',
  amountMinor,
  ...extra,
});

